import type { Media } from '@/payload-types'

type MaybeMedia = number | Media | null | undefined

/**
 * Resolves a usable URL for an upload field value.
 * When NEXT_PUBLIC_CLOUDFLARE_PUB_URL is set (public R2 bucket), files are
 * served straight from it; otherwise the URL generated by Payload is used.
 */
export function mediaUrl(media: MaybeMedia, fallback?: string): string | undefined {
  if (!media || typeof media === 'number') return fallback
  const publicBase = process.env.NEXT_PUBLIC_CLOUDFLARE_PUB_URL
  if (publicBase && media.filename) {
    return `${publicBase.replace(/\/$/, '')}/${encodeURIComponent(media.filename)}`
  }
  return toRelative(media.url) || fallback
}

/** Same-origin URLs are made relative so next/image serves them locally. */
function toRelative(url?: string | null) {
  if (!url) return undefined
  const origin = process.env.NEXT_PUBLIC_SERVER_URL?.replace(/\/$/, '')
  if (origin && url.startsWith(`${origin}/`)) return url.slice(origin.length)
  return url
}

export function mediaAlt(media: MaybeMedia, fallback = ''): string {
  if (!media || typeof media === 'number') return fallback
  return media.alt || fallback
}

/** CSS object-position from the focal point chosen in the admin. */
export function mediaPosition(media: MaybeMedia): string | undefined {
  if (!media || typeof media === 'number') return undefined
  if (typeof media.focalX !== 'number' || typeof media.focalY !== 'number') return undefined
  return `${media.focalX}% ${media.focalY}%`
}
